String fn0(List<List<int>> cells) {
  if (cells.isEmpty) return 'union: 0, bounding: 0, efficiency: 0%';

  final xsSet = <int>{};
  final ysSet = <int>{};

  for (var cell in cells) {
    xsSet.add(cell[0]);
    xsSet.add(cell[2]);
    ysSet.add(cell[1]);
    ysSet.add(cell[3]);
  }

  final xs = xsSet.toList()..sort();
  final ys = ysSet.toList()..sort();

  final minX = xs.first;
  final maxX = xs.last;
  final minY = ys.first;
  final maxY = ys.last;

  final boundingArea = (maxX - minX) * (maxY - minY);

  int unionArea = 0;

  for (var i = 0; i < xs.length - 1; i++) {
    final x1 = xs[i];
    final x2 = xs[i + 1];

    for (var j = 0; j < ys.length - 1; j++) {
      final y1 = ys[j];
      final y2 = ys[j + 1];

      bool covered = false;
      for (var cell in cells) {
        if (x1 >= cell[0] && x2 <= cell[2] && y1 >= cell[1] && y2 <= cell[3]) {
          covered = true;
          break;
        }
      }

      if (covered) {
        unionArea += (x2 - x1) * (y2 - y1);
      }
    }
  }

  double efficiency = boundingArea == 0 ? 0.0 : unionArea / boundingArea * 100.0;

  return 'union: $unionArea, bounding: $boundingArea, efficiency: ${efficiency.round()}%';
}

