String fn0(String shelfCodes, int threshold) {
  if (shelfCodes.isEmpty) return '';

  var parts = shelfCodes.split('|');
  var result = <String>[];

  for (var part in parts) {
    if (part.isEmpty) continue;

    var idx = part.indexOf(':');
    if (idx == -1) continue;

    var name = part.substring(0, idx);
    var valueStr = part.substring(idx + 1);
    var value = int.parse(valueStr);

    if (value > threshold) continue;

    if (value == threshold) {
      result.add('$name=0');
    } else {
      result.add('$name!${threshold - value}');
    }
  }

  return result.join(',');
}

