  final List<List<int>> stack = [];
  bool result = false;

  for (final event in events) {
    final parts = event.split(' ');
    final cmd = parts[0];
    final value = int.parse(parts[1]);

    switch (cmd) {
      case 'batch':
        stack.add([value, 0]);
        break;
      case 'add':
        stack.last[1] += value;
        break;
      case 'undo':
        stack.last[1] -= value;
        break;
      case 'seal':
        final frame = stack.removeLast();
        final bool ok = frame[0] == frame[1];
        result = ok;
        if (ok && stack.isNotEmpty) {
          stack.last[1] += frame[1];
        }
        break;
      default:
        break;
    }
  }

